{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "A prazosin dimer (compound 27) was detected in mouse brain at 10-20% of blood concentration after systemic administration, demonstrating measurable CNS exposure for the prazosin core scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "[11C]prazosin and [11C]bunazosin showed limited BBB permeability and were deemed unsuitable for PET neuroimaging, indicating restricted brain uptake for this scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "[11C]GB67, a close prazosin analog, also showed limited BBB permeability, reinforcing the restricted-uptake phenotype for this scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "A related quinazoline achieved Kpuu,brain of 0.34 and was labeled good brain penetration, showing that quinazoline-based structures can achieve meaningful CNS access when optimized.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The prazosin scaffold shows measurable brain accumulation (10-20% of blood) and prazosin is a clinically CNS-active alpha-1 antagonist; PET unsuitability reflects limited uptake/efflux but does not rule out meaningful CNS access.",
  "evidence_gaps": [
    "No direct Kpuu,brain or unbound brain exposure value for prazosin itself is provided.",
    "PET data are qualitative and focused on imaging suitability rather than therapeutic CNS access.",
    "The supportive brain-tissue measurement is from a prazosin dimer, which may not fully reflect monomer pharmacokinetics."
  ],
